    <td background="images/bg.gif"><font class=""><a href="modules.php?name=News&new_topic=6">Magazines</a></font><br><font class="testo_notizia" color="#000000"><b>[<a href="modules.php?name=&amp;file=categories&amp;op=newindex&amp;catid=12"><font class="esclusiva">The First Look</font></a>] Madonna in Dream'Up - Feb 2005.</b></font></td>
